#include "ContaminationRuntime.hpp"
namespace elysium::world {bool ContaminationRuntime::set(Contamination c,std::string&w){if(!c.carrier||!c.type){w="invalid contamination";return false;}c.load=std::max(0.0,std::isfinite(c.load)?c.load:0.0);rows_[c.carrier]=c;return true;}double ContaminationRuntime::transfer(StableId f,StableId t,double x){auto a=rows_.find(f),b=rows_.find(t);if(a==rows_.end()||b==rows_.end()||a->second.type!=b->second.type)return 0;x=std::clamp(std::isfinite(x)?x:0.0,0.0,1.0);double moved=a->second.load*x;a->second.load-=moved;b->second.load+=moved;++a->second.revision;++b->second.revision;return moved;}double ContaminationRuntime::clean(StableId id,double a){auto i=rows_.find(id);if(i==rows_.end())return 0;a=std::max(0.0,a);double r=std::min(a,i->second.load);i->second.load-=r;++i->second.revision;return r;}std::optional<Contamination>ContaminationRuntime::get(StableId id)const{auto i=rows_.find(id);if(i==rows_.end())return std::nullopt;return i->second;}}
